(function () {

    const root = root_element || document;

    function update_val(id, val) {
        const el = root.querySelector(`#${id}`);
        if (el) el.innerText = val ?? 0;
    }

    function refresh_stats() {
        frappe.call({
            method: 'audit_management.audit_management.dashboard.get_dashboard_stats',
            callback: function (r) {

                if (!r.message || !r.message.success) return;

                const m = r.message;
                const role = m.role_type;

                update_val('stat-pending', m.pending_for_me);
                update_val('stat-responded', m.responded_by_me);

                update_val('stat-total', m.total_pending);

                const quickActions = root.querySelector('.quick-actions-section');
                if (quickActions) {
                    if (role === "stage_user") {
                        quickActions.style.display = "none";
                    } else {
                        quickActions.style.display = "block";
                    }
                }

                const cards = root.querySelectorAll('.stat-card');


                // 0 = Pending
                // 1 = My Response
                // 2 = Total
                // 3 = High Risk
                // 4 = Closed

                if (role === "stage_user") {

                    // ✅ show only Pending + My Response
                    if (cards[0]) cards[0].style.display = "flex";
                    if (cards[1]) cards[1].style.display = "flex";

                    // ❌ hide others
                    if (cards[2]) cards[2].style.display = "none";
                    if (cards[3]) cards[3].style.display = "none";
                    if (cards[4]) cards[4].style.display = "none";

                } else {

                    // ❌ hide stage specific
                    if (cards[0]) cards[0].style.display = "none";
                    if (cards[1]) cards[1].style.display = "none";

                    // ✅ show rest
                    if (cards[2]) cards[2].style.display = "flex";
                    if (cards[3]) cards[3].style.display = "flex";
                    if (cards[4]) cards[4].style.display = "flex";

                    update_val('stat-high', m.high_risk);
                    update_val('stat-tat', m.closed_count);
                }

                // -------------------------------
                // SECTION CONTROL
                // -------------------------------

                const pendingSection = root.querySelector('#pending-action-section');
                const pendingContainer = root.querySelector('#pending-items-list');

                const detailedSection = root.querySelector('#detailed-queries-section');
                const tbody = root.querySelector('#detailed-queries-body');

                if (!pendingSection || !detailedSection) return;

                if (role === "stage_user") {

                    // ✅ Stage user → only pending
                    if (m.pending_list?.length) {
                        pendingSection.style.display = 'block';

                        pendingContainer.innerHTML = m.pending_list.map(item => `
                            <div class='pending-item-card ${(item.risk || 'normal').toLowerCase()}'
                                onclick="frappe.set_route('Form', 'My Audits', '${item.name}')">

                                <div class='item-info'>
                                    <span class='item-name'>${item.name}</span>
                                    <span class='item-subject'>${item.audit_query_subject_box || 'No Subject'}</span>
                                </div>

                                <div class='item-meta'>
                                    <span class='risk-badge'>${item.risk || 'Normal'} Risk</span>
                                    <i class='fa fa-chevron-right'></i>
                                </div>
                            </div>
                        `).join('');
                    } else {
                        pendingSection.style.display = 'none';
                    }

                    detailedSection.style.display = 'none';

                } else {

                    // ❌ hide pending
                    pendingSection.style.display = 'none';

                    // ✅ show recent
                    if (m.recent_list?.length && tbody) {
                        detailedSection.style.display = 'block';

                        tbody.innerHTML = m.recent_list.map(item => `
                            <tr onclick="frappe.set_route('Form', 'My Audits', '${item.name}')">
                                <td>${item.name}</td>
                                <td>${item.audit_query_subject_box || 'No Subject'}</td>
                                <td>${item.emp_branch || '-'}</td>
                                <td>${item.emp_division || '-'}</td>
                                <td><span class="status-pill">${item.status || '-'}</span></td>
                                <td>
                                    <span class="risk-tag ${(item.risk || 'normal').toLowerCase()}">
                                        ${item.risk || 'Normal'}
                                    </span>
                                </td>
                            </tr>
                        `).join('');
                    } else {
                        detailedSection.style.display = 'none';
                    }
                }
            }
        });
    }

    window.load_my_pending = function() {
    frappe.call({
        method: "audit_management.audit_management.dashboard.get_my_pending_records",
        callback: function(r) {
            if (r.message && r.message.length) {
                frappe.set_route("List", "My Audits", {
                    name: ["in", r.message]
                });
            } else {
                frappe.msgprint("No pending records");
            }
        }
    });
};

window.load_my_responded = function() {
    frappe.call({
        method: "audit_management.audit_management.dashboard.get_my_responded_records",
        callback: function(r) {
            if (r.message && r.message.length) {
                frappe.set_route("List", "My Audits", {
                    name: ["in", r.message]
                });
            } else {
                frappe.msgprint("No responded records found");
            }
        }
    });
};


    // ✅ IMPORTANT (workspace reload fix)
    $(document).on('workspace_render', function () {
        refresh_stats();
    });

    refresh_stats();

})();

style:
.modern-audit-dashboard { 
    font-family: 'Inter', -apple-system, sans-serif; 
    padding: 28px; 
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
    border-radius: 20px; 
    border: 1px solid rgba(226, 232, 240, 0.6); 
}

/* HEADER */
.header-section { margin-bottom: 30px; }

.main-title { 
    font-size: 26px; 
    font-weight: 800; 
    color: #0f172a; 
}

/* GRID */
.stats-grid { 
    display: grid; 
    grid-template-columns: repeat(4, 1fr); 
    gap: 18px; 
    margin-bottom: 32px; 
}

/* CARD */
.stat-card { 
    display: flex; 
    align-items: center; 
    gap: 18px; 
    padding: 20px; 
    border-radius: 16px; 
    cursor: pointer; 
    transition: all 0.25s ease; 
    border: 1px solid rgba(226,232,240,0.7);
    backdrop-filter: blur(6px);
    background: rgba(255,255,255,0.7);
    position: relative;
}

/* Pastel left border */
.stat-card::before {
    content: "";
    width: 4px;
    height: 100%;
    position: absolute;
    left: 0;
    top: 0;
    border-radius: 16px 0 0 16px;
}

/* Hover effect */
.stat-card:hover { 
    transform: translateY(-4px); 
    box-shadow: 0 10px 25px rgba(0,0,0,0.08);
}

/* CARD COLORS (PASTEL) */
.stat-card.blue::before { background: #93c5fd; }
.stat-card.purple::before { background: #c4b5fd; }
.stat-card.red::before { background: #fca5a5; }
.stat-card.orange::before { background: #fde68a; }

/* ICON */
.icon-box { 
    width: 48px; 
    height: 48px; 
    border-radius: 12px;
    display: flex; 
    align-items: center; 
    justify-content: center;
    font-size: 18px;
    transition: 0.25s;
}

.stat-card.blue .icon-box { 
    background: linear-gradient(135deg, #eff6ff, #dbeafe);
    color: #2563eb;
}

.stat-card.purple .icon-box { 
    background: linear-gradient(135deg, #f5f3ff, #ede9fe);
    color: #7c3aed;
}

.stat-card.red .icon-box { 
    background: linear-gradient(135deg, #fef2f2, #fee2e2);
    color: #dc2626;
}

.stat-card.orange .icon-box { 
    background: linear-gradient(135deg, #fffbeb, #fef3c7);
    color: #d97706;
}

/* STAT INFO - CHANGED TO FLEX FOR SINGLE LINE */
.stat-info { 
    display: flex; 
    align-items: baseline; 
    gap: 10px; 
    width: 100%;
}

.stat-info .val { 
    font-size: 26px; 
    font-weight: 800; 
    color: #0f172a;
    line-height: 1;
}

.stat-info .lbl { 
    font-size: 11px; 
    font-weight: 600; 
    color: #64748b; 
    text-transform: uppercase;
    line-height: 1;
}

/* QUICK ACTIONS */
.actions-flex { 
    display: flex; 
    gap: 12px; 
    flex-wrap: wrap; 
    margin-bottom: 30px; 
}

.btn-modern { 
    padding: 10px 18px; 
    border-radius: 10px; 
    font-size: 13px; 
    font-weight: 600; 
    border: 1px solid #e2e8f0;
    transition: 0.25s;
}

.btn-modern.primary { 
    background: linear-gradient(135deg, #1e293b, #0f172a);
    color: white;
    box-shadow: 0 6px 16px rgba(0,0,0,0.15);
}

.btn-modern.primary:hover {
    transform: translateY(-2px);
}

.btn-modern.secondary {
    background: #ffffff;
    color: #334155;
}

.btn-modern.secondary:hover {
    background: #f8fafc;
}

/* PENDING ITEMS */
.pending-item-card {
    background: white;
    border-radius: 12px;
    padding: 14px 18px;
    border-left: 4px solid #cbd5e0;
    transition: 0.2s;
}

.pending-item-card:hover {
    transform: translateX(4px);
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .stats-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 576px) {
  .stats-grid { grid-template-columns: 1fr; }
}
